import 'package:flutter/material.dart';import 'package:flutter_svg/flutter_svg.dart';import 'package:zan/Config/Assets/image_svg.dart';import 'package:zan/Core/Resources/app_fonts.dart';import 'package:zan/Core/Utils/Extensions/localizations_extension.dart';import 'package:zan/Core/Utils/Extensions/widget_extension.dart';class CartScreen extends StatelessWidget {  const CartScreen({super.key});  @override  Widget build(BuildContext context) {    return Scaffold(      appBar: AppBar(        title: Text(          context.local.cart,          style: AppTextStyles.h6Bold,        ),        centerTitle: true,      ),      body: Column(        mainAxisAlignment: MainAxisAlignment.center,        children: [          SvgPicture.asset(AppImagesSvg.cartEmpty).stylePagesInOther,          Text(            context.local.massageInCart,            style: AppTextStyles.bodyMediumBold,          )        ],      ),    );  }}